values ('imi_cila', $q$إيميبينيم–سيلاستاتين$q$, $q$Imipenem–cilastatin$q$, 'watch', $q$كاربابينيمات$q$, $q$Carbapenems$q$, $q$عدوى الجهاز التنفسي السفلي، المسالك البولية، البطن، العدوى النسائية، تسمم الدم، العظام والمفاصل، الجلد، والتهاب الشغاف.$q$, $q$Lower respiratory, urinary, intra-abdominal, gynaecological, septicaemia, bone and joint, skin infections, and endocarditis.$q$, $q$للبالغين (تصفية 90 فأكثر) بجرعة الإيميبينيم: البكتيريا الحساسة 500 ملغ كل 6 ساعات أو 1000 ملغ كل 8 ساعات؛ متوسطة الحساسية 1000 ملغ كل 6 ساعات. 500 ملغ أو أقل خلال 20 إلى 30 دقيقة، والأكثر خلال 40 إلى 60 دقيقة.$q$, $q$Adults (clearance 90 or more), as imipenem: susceptible bacteria 500 mg every 6 h or 1000 mg every 8 h; intermediate susceptibility 1000 mg every 6 h. 500 mg or less over 20 to 30 minutes, more over 40 to 60 minutes.$q$, $q$حسب الجرعة الأصلية والتصفية: 500 كل 6 ← 400 كل 6 (60 إلى 89)، 300 كل 6 (30 إلى 59)، 200 كل 6 (15 إلى 29). 1000 كل 8 ← 500 كل 6، 500 كل 8، 500 كل 12. 1000 كل 6 ← 750 كل 8، 500 كل 6، 500 كل 12. أقل من 15: لا يُعطى إلا إذا بدأ الغسيل خلال 48 ساعة.$q$, $q$By the starting dose and clearance: 500 every 6 h → 400 every 6 h (60 to 89), 300 every 6 h (30 to 59), 200 every 6 h (15 to 29). 1000 every 8 h → 500 every 6 h, 500 every 8 h, 500 every 12 h. 1000 every 6 h → 750 every 8 h, 500 every 6 h, 500 every 12 h. Under 15: not unless dialysis starts within 48 h.$q$, $q$تسريب وريدي؛ يُبطأ عند الغثيان.$q$, $q$IV infusion; slow it down if nausea occurs.$q$, '{73}', 730, false, false, false)
on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, aware = excluded.aware, class_ar = excluded.class_ar, class_en = excluded.class_en, uses_ar = excluded.uses_ar, uses_en = excluded.uses_en, dose_ar = excluded.dose_ar, dose_en = excluded.dose_en, renal_ar = excluded.renal_ar, renal_en = excluded.renal_en, timing_ar = excluded.timing_ar, timing_en = excluded.timing_en, source_ids = excluded.source_ids, sort = excluded.sort, reviewed = false, deleted = false, updated_at = now();
