values ('colistin', $q$كوليستيمثات (كوليستين)$q$, $q$Colistimethate (colistin)$q$, 'reserve', $q$بوليميكسينات$q$, $q$Polymyxins$q$, $q$العدوى الحادة أو المزمنة بالعصيات سلبية الغرام الحساسة (الأمعائيات، الإشريكية، الكلبسيلة، الزائفة الزنجارية).$q$, $q$Acute or chronic infections by susceptible Gram-negative bacilli (Enterobacter, E. coli, Klebsiella, Pseudomonas aeruginosa).$q$, $q$البالغون والأطفال، وريدياً أو عضلياً: 2.5 إلى 5 ملغ/كغ يومياً من الكوليستين القاعدي، مقسمة 2 إلى 4 جرعات، لا تتجاوز 5 ملغ/كغ يومياً. السمنة: بالوزن المثالي.$q$, $q$Adults and children, IV or IM: 2.5 to 5 mg/kg a day of colistin base, in 2 to 4 doses, not over 5 mg/kg a day. Obesity: ideal weight.$q$, $q$التصفية 50 إلى 79 ← 2.5 إلى 3.8 ملغ/كغ يومياً على جرعتين؛ 30 إلى 49 ← 2.5 ملغ/كغ يومياً مرة أو على جرعتين؛ 10 إلى 29 ← 1.5 ملغ/كغ كل 36 ساعة.$q$, $q$Clearance 50 to 79 → 2.5 to 3.8 mg/kg a day in 2 doses; 30 to 49 → 2.5 mg/kg a day once or in 2 doses; 10 to 29 → 1.5 mg/kg every 36 h.$q$, $q$حقن وريدي بطيء خلال 3 إلى 5 دقائق، أو تسريب. الجرعات بالكوليستين القاعدي (قارورة 150 ملغ).$q$, $q$Slow IV injection over 3 to 5 minutes, or infusion. Doses as colistin base (150 mg vial).$q$, '{120}', 1200, false, false, false)
on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, aware = excluded.aware, class_ar = excluded.class_ar, class_en = excluded.class_en, uses_ar = excluded.uses_ar, uses_en = excluded.uses_en, dose_ar = excluded.dose_ar, dose_en = excluded.dose_en, renal_ar = excluded.renal_ar, renal_en = excluded.renal_en, timing_ar = excluded.timing_ar, timing_en = excluded.timing_en, source_ids = excluded.source_ids, sort = excluded.sort, reviewed = false, deleted = false, updated_at = now();
delete from public.antibiotic_interactions where drug_id = 'colistin';
values ('polymyxin_b', $q$بوليميكسين ب$q$, $q$Polymyxin B$q$, 'reserve', $q$بوليميكسينات$q$, $q$Polymyxins$q$, $q$العدوى الحادة بالزائفة الزنجارية الحساسة (ومنها المسالك والسحايا وتجرثم الدم)، وبعض سلبيات الغرام الأخرى عند عدم ملاءمة الأدوية الأقل سمية.$q$, $q$Acute infections by susceptible Pseudomonas aeruginosa (including urinary, meningeal and bloodstream), and some other Gram-negative infections when less toxic drugs are unsuitable.$q$, $q$وريدياً: 15000 إلى 25000 وحدة/كغ يومياً (لا تتجاوز 25000)، يمكن كل 12 ساعة. عضلياً (غير مفضل للألم): 25000 إلى 30000 وحدة/كغ يومياً مقسمة كل 4 إلى 6 ساعات. داخل القراب (السحايا): 50000 وحدة يومياً 3 إلى 4 أيام ثم يوماً بعد يوم.$q$, $q$IV: 15,000 to 25,000 units/kg a day (not over 25,000), can be every 12 h. IM (not preferred, painful): 25,000 to 30,000 units/kg a day divided every 4 to 6 h. Intrathecal (meningitis): 50,000 units daily for 3 to 4 days, then every other day.$q$, $q$ضعف الكلى: تُخفض من 15000 وحدة/كغ نزولاً (لا يعطي الملصق جدولاً). يُوقف عند نقص البول وارتفاع اليوريا.$q$, $q$Kidney impairment: reduce downward from 15,000 units/kg (the label gives no table). Stop if urine output falls and urea rises.$q$, $q$وريدياً بالتنقيط المستمر في دكستروز 5%. في المستشفى مع مراقبة الكلى (تحذير الملصق: سمية كلوية وعصبية).$q$, $q$IV by continuous drip in 5% dextrose. In hospital with kidney monitoring (label warning: kidney and nerve toxicity).$q$, '{121}', 1210, false, false, false)
on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, aware = excluded.aware, class_ar = excluded.class_ar, class_en = excluded.class_en, uses_ar = excluded.uses_ar, uses_en = excluded.uses_en, dose_ar = excluded.dose_ar, dose_en = excluded.dose_en, renal_ar = excluded.renal_ar, renal_en = excluded.renal_en, timing_ar = excluded.timing_ar, timing_en = excluded.timing_en, source_ids = excluded.source_ids, sort = excluded.sort, reviewed = false, deleted = false, updated_at = now();
delete from public.antibiotic_interactions where drug_id = 'polymyxin_b';
values ('fusidic', $q$حمض الفوسيديك (فموي)$q$, $q$Fusidic acid (oral)$q$, 'watch', $q$ستيرويدات مضادة للجراثيم$q$, $q$Steroid antibacterials$q$, $q$عدوى العنقوديات: الجلد، والتهاب العظم والنقي، والتهاب الرئة، وتسمم الدم، والجروح، والتهاب الشغاف، والتليف الكيسي المختلط.$q$, $q$Staphylococcal infections: skin, osteomyelitis, pneumonia, septicaemia, wounds, endocarditis, and superinfected cystic fibrosis.$q$, $q$(فوسيدات الصوديوم) الجلد: 250 ملغ مرتين يومياً 5 إلى 10 أيام. العدوى الأخرى: 500 ملغ 3 مرات يومياً، ويمكن مضاعفتها في الحالات الشديدة.$q$, $q$(Sodium fusidate) Skin: 250 mg twice a day for 5 to 10 days. Other infections: 500 mg three times a day, doubled in severe cases.$q$, $q$لا تعديل في ضعف الكلى أو الغسيل (يُطرح في الصفراء). بحذر مع ضعف الكبد ومراقبته.$q$, $q$No change for kidney impairment or dialysis (excreted in bile). Caution and monitoring with liver impairment.$q$, $q$فموياً.$q$, $q$By mouth.$q$, '{122}', 1220, false, false, false)
on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, aware = excluded.aware, class_ar = excluded.class_ar, class_en = excluded.class_en, uses_ar = excluded.uses_ar, uses_en = excluded.uses_en, dose_ar = excluded.dose_ar, dose_en = excluded.dose_en, renal_ar = excluded.renal_ar, renal_en = excluded.renal_en, timing_ar = excluded.timing_ar, timing_en = excluded.timing_en, source_ids = excluded.source_ids, sort = excluded.sort, reviewed = false, deleted = false, updated_at = now();
delete from public.antibiotic_interactions where drug_id = 'fusidic';
values ('fidaxo', $q$فيداكسومايسين$q$, $q$Fidaxomicin$q$, 'watch', $q$ماكروسيكلينات$q$, $q$Macrocyclic antibiotics$q$, $q$إسهال المطثية العسيرة (Clostridioides difficile).$q$, $q$Clostridioides difficile diarrhoea.$q$, $q$للبالغين: 200 ملغ مرتين يومياً لمدة 10 أيام.$q$, $q$Adults: 200 mg twice a day for 10 days.$q$, $q$لا تعديل في ضعف الكلى.$q$, $q$No change for kidney impairment.$q$, $q$مع الطعام أو بدونه. لا يُمتص كثيراً؛ لا يُستعمل للعدوى الجهازية.$q$, $q$With or without food. Little is absorbed; not for systemic infections.$q$, '{123}', 1230, false, false, false)
on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, aware = excluded.aware, class_ar = excluded.class_ar, class_en = excluded.class_en, uses_ar = excluded.uses_ar, uses_en = excluded.uses_en, dose_ar = excluded.dose_ar, dose_en = excluded.dose_en, renal_ar = excluded.renal_ar, renal_en = excluded.renal_en, timing_ar = excluded.timing_ar, timing_en = excluded.timing_en, source_ids = excluded.source_ids, sort = excluded.sort, reviewed = false, deleted = false, updated_at = now();
