values ('lefamulin', $q$ليفامولين$q$, $q$Lefamulin$q$, 'reserve', $q$بليوروموتيلينات$q$, $q$Pleuromutilins$q$, $q$التهاب الرئة الجرثومي المكتسب من المجتمع للبالغين.$q$, $q$Community-acquired bacterial pneumonia in adults.$q$, $q$150 ملغ وريدياً خلال 60 دقيقة كل 12 ساعة 5 إلى 7 أيام (يمكن التحويل إلى الأقراص)، أو 600 ملغ فموياً كل 12 ساعة 5 أيام.$q$, $q$150 mg IV over 60 minutes every 12 h for 5 to 7 days (switching to tablets is possible), or 600 mg by mouth every 12 h for 5 days.$q$, $q$لا تعديل في ضعف الكلى أو الغسيل. ضعف الكبد الشديد (Child-Pugh C): الوريدي 150 ملغ كل 24 ساعة؛ الأقراص لا يُنصح بها في الضعف المتوسط أو الشديد.$q$, $q$No change for kidney impairment or dialysis. Severe liver impairment (Child-Pugh C): IV 150 mg every 24 h; tablets not recommended in moderate or severe impairment.$q$, $q$الأقراص قبل الطعام بساعة أو بعده بساعتين، تُبلع كاملة مع الماء. يطيل QT. قد يضر الجنين: التأكد من عدم الحمل.$q$, $q$Tablets 1 hour before or 2 hours after a meal, swallowed whole with water. Prolongs QT. May harm the fetus: check for pregnancy.$q$, '{125}', 1250, false, false, false)
on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, aware = excluded.aware, class_ar = excluded.class_ar, class_en = excluded.class_en, uses_ar = excluded.uses_ar, uses_en = excluded.uses_en, dose_ar = excluded.dose_ar, dose_en = excluded.dose_en, renal_ar = excluded.renal_ar, renal_en = excluded.renal_en, timing_ar = excluded.timing_ar, timing_en = excluded.timing_en, source_ids = excluded.source_ids, sort = excluded.sort, reviewed = false, deleted = false, updated_at = now();
delete from public.antibiotic_interactions where drug_id = 'lefamulin';
values ('pristina', $q$بريستيناميسين$q$, $q$Pristinamycin$q$, 'watch', $q$ستربتوغرامينات (سينرجيستينات)$q$, $q$Streptogramins (synergistins)$q$, $q$للبالغين والأطفال: التهاب الجيوب الفكية الحاد، وتفاقم التهاب القصبات المزمن، والتهاب الرئة المكتسب الخفيف إلى المتوسط، وعدوى الجلد والأنسجة الرخوة.$q$, $q$Adults and children: acute maxillary sinusitis, exacerbations of chronic bronchitis, mild to moderate community pneumonia, and skin and soft tissue infections.$q$, $q$للبالغين: الجيوب 1 غرام مرتين يومياً 4 أيام؛ القصبات 1 غرام 3 مرات يومياً 4 أيام؛ الرئة 1 غرام 3 مرات يومياً 7 إلى 14 يوماً؛ الجلد 1 غرام مرتين إلى 3 مرات يومياً 8 إلى 14 يوماً؛ حتى 4 غرامات يومياً في الحالات الشديدة. الأطفال: 50 ملغ/كغ يومياً على 2 أو 3 جرعات (حتى 100 ملغ/كغ، دون تجاوز جرعة البالغ).$q$, $q$Adults: sinusitis 1 g twice a day for 4 days; bronchitis 1 g three times a day for 4 days; pneumonia 1 g three times a day for 7 to 14 days; skin 1 g two to three times a day for 8 to 14 days; up to 4 g a day in severe cases. Children: 50 mg/kg a day in 2 or 3 doses (up to 100 mg/kg, not over the adult dose).$q$, $q$لا تعديل في ضعف الكلى.$q$, $q$No change for kidney impairment.$q$, $q$مع الوجبات، والأقراص مع مشروب.$q$, $q$With meals; swallow the tablets with a drink.$q$, '{126}', 1260, false, false, false)
on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, aware = excluded.aware, class_ar = excluded.class_ar, class_en = excluded.class_en, uses_ar = excluded.uses_ar, uses_en = excluded.uses_en, dose_ar = excluded.dose_ar, dose_en = excluded.dose_en, renal_ar = excluded.renal_ar, renal_en = excluded.renal_en, timing_ar = excluded.timing_ar, timing_en = excluded.timing_en, source_ids = excluded.source_ids, sort = excluded.sort, reviewed = false, deleted = false, updated_at = now();
